content:
Below is a clean Terraform module layout that provisions:

- **S3 bucket** with:
  - versioning
  - server-side encryption
  - public access blocked
- **RDS PostgreSQL** with:
  - deletion protection
  - backup retention
  - not publicly accessible
- **IAM role for service accounts**
  - supports OIDC trust for Kubernetes service accounts
  - least-privilege inline policy for S3 access

It also supports **dev/prod** via **tfvars** and can also work with **workspaces**.

---

# Suggested structure

```text
terraform/
├── main.tf
├── variables.tf
├── outputs.tf
├── versions.tf
├── dev.tfvars
├── prod.tfvars
└── modules/
    ├── s3_bucket/
    │   ├── main.tf
    │   ├── variables.tf
    │   └── outputs.tf
    ├── rds_postgres/
    │   ├── main.tf
    │   ├── variables.tf
    │   └── outputs.tf
    └── iam_service_account_role/
        ├── main.tf
        ├── variables.tf
        └── outputs.tf
```

---

# Root module

## `versions.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}
```

---

## `variables.tf`

```hcl
variable "aws_region" {
  description = "AWS region"
  type        = string
}

variable "environment" {
  description = "Environment name, e.g. dev or prod"
  type        = string
}

variable "project_name" {
  description = "Project/application name"
  type        = string
}

variable "bucket_name" {
  description = "S3 bucket name"
  type        = string
}

variable "enable_replication" {
  description = "Enable cross-region replication for S3 bucket"
  type        = bool
  default     = false
}

variable "replication_destination_bucket_arn" {
  description = "Destination bucket ARN for replication"
  type        = string
  default     = null
}

variable "db_name" {
  description = "Initial PostgreSQL database name"
  type        = string
}

variable "db_username" {
  description = "RDS master username"
  type        = string
  sensitive   = true
}

variable "db_password" {
  description = "RDS master password"
  type        = string
  sensitive   = true
}

variable "db_instance_class" {
  description = "RDS instance class"
  type        = string
}

variable "db_allocated_storage" {
  description = "RDS allocated storage"
  type        = number
  default     = 20
}

variable "db_multi_az" {
  description = "Enable Multi-AZ deployment"
  type        = bool
  default     = false
}

variable "db_storage_encrypted" {
  description = "Enable storage encryption"
  type        = bool
  default     = true
}

variable "db_subnet_ids" {
  description = "Private subnet IDs for RDS subnet group"
  type        = list(string)
}

variable "vpc_security_group_ids" {
  description = "Security groups for RDS"
  type        = list(string)
}

variable "oidc_provider_arn" {
  description = "OIDC provider ARN for EKS service account trust"
  type        = string
}

variable "oidc_provider_url" {
  description = "OIDC provider URL without https:// for trust condition"
  type        = string
}

variable "k8s_namespace" {
  description = "Kubernetes namespace of the service account"
  type        = string
}

variable "k8s_service_account_name" {
  description = "Kubernetes service account name"
  type        = string
}
```

---

## `main.tf`

```hcl
provider "aws" {
  region = var.aws_region
}

locals {
  name_prefix = "${var.project_name}-${var.environment}"
}

module "assets_bucket" {
  source = "./modules/s3_bucket"

  bucket_name                         = var.bucket_name
  enable_replication                  = var.enable_replication
  replication_destination_bucket_arn  = var.replication_destination_bucket_arn

  tags = {
    Project     = var.project_name
    Environment = var.environment
  }
}

module "postgres" {
  source = "./modules/rds_postgres"

  identifier             = "${local.name_prefix}-postgres"
  db_name                = var.db_name
  username               = var.db_username
  password               = var.db_password
  instance_class         = var.db_instance_class
  allocated_storage      = var.db_allocated_storage
  multi_az               = var.db_multi_az
  storage_encrypted      = var.db_storage_encrypted
  subnet_ids             = var.db_subnet_ids
  vpc_security_group_ids = var.vpc_security_group_ids

  tags = {
    Project     = var.project_name
    Environment = var.environment
  }
}

module "service_account_role" {
  source = "./modules/iam_service_account_role"

  role_name                 = "${local.name_prefix}-sa-role"
  oidc_provider_arn         = var.oidc_provider_arn
  oidc_provider_url         = var.oidc_provider_url
  namespace                 = var.k8s_namespace
  service_account_name      = var.k8s_service_account_name
  bucket_arn                = module.assets_bucket.bucket_arn
  environment               = var.environment

  tags = {
    Project     = var.project_name
    Environment = var.environment
  }
}
```

---

## `outputs.tf`

```hcl
output "bucket_id" {
  value = module.assets_bucket.bucket_id
}

output "bucket_arn" {
  value = module.assets_bucket.bucket_arn
}

output "rds_instance_endpoint" {
  value = module.postgres.endpoint
}

output "rds_instance_arn" {
  value = module.postgres.db_instance_arn
}

output "service_account_role_arn" {
  value = module.service_account_role.role_arn
}
```

